'use strict';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,n=2)=>x==null?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:n,minimumFractionDigits:n});
const pct=x=>x==null?'—':(x>0?'+':'')+fmt(x)+'%';
const currency=(x,c)=>x==null?'—':new Intl.NumberFormat(undefined,{style:'currency',currency:c||'CAD',maximumFractionDigits:c==='KRW'?0:2}).format(x);
const pages=['Overview','Markets','Watchlist','Screener','Strategies','Backtest','Paper Trading','Portfolio','News','Learn','Trading Vault'];
const icons=['◫','◉','☆','≡','⌘','↗','▣','◈','▤','◷','▧'];
let token='',state={},market=localStorage.getItem('stock101.market')||'CA',selected=localStorage.getItem('stock101.symbol')||'SHOP.TO',page='Overview',analysis=null,strategy=null,latestBacktest=null,chartRange='1Y',viewVersion=0;
const cache=new Map();
const labels={Overview:['Your market, in focus.','Understand the signals. See the risks. Make your own decisions.'],Markets:['Follow the bigger picture.','Explore companies, funds and the direction of their market.'],Watchlist:['Keep an eye on what matters.','Your saved companies, always within reach.'],Screener:['Find your starting point.','Turn an idea into a short list worth researching.'],Strategies:['An idea. A set of rules.','Build a strategy you can explain, then test it before trusting it.'],Backtest:['Let history challenge your idea.','See what your rules would have done, including the difficult days.'],'Paper Trading':['A place to practice.','Virtual money. Real calculations. No brokerage orders.'],Portfolio:['See the whole picture.','Track your paper holdings and cash, one currency at a time.'],News:['The story behind the ticker.','Dated sources first. Interpretation second.'],Learn:['Make the market less mysterious.','Small lessons, with examples from the stock you are exploring.'],'Trading Vault':['Your trading reference library.','The supplied operating notes, with implementation status kept explicit.'],Settings:['Your workspace, your pace.','Connections and trading permissions only when you are ready.']};
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6000);}
async function api(path='',body){const r=await fetch('/api/stock101'+(path?'/'+path:''),{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-AIRI-Token':token},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok||d.ok===false)throw Error(d.message||d.error||d.code||'Request failed');return d;}
const act=(action,data={})=>api('',{action,...data});
const loading=(text='Reading your market data…')=>`<div class="card empty loading">${esc(text)}</div>`;
const errorBox=e=>`<div class="notice warning"><strong>We couldn't load this yet.</strong><br>${esc(e.message)}<br>Try again, or import your own sourced price data in Settings.</div>`;
const button=(id,text,primary=false)=>`<button id="${id}" class="button ${primary?'primary':'secondary'}">${text}</button>`;
function bind(id,fn){const e=$('#'+id);if(e)e.onclick=async()=>{e.disabled=true;try{await fn();}catch(x){toast(x.message);}finally{e.disabled=false;}};}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
$('#modal-close').onclick=()=>$('#modal').close();
function updateStage(){const names=['Analysis only','Backtesting enabled','Paper trading'];$('#stage-label').textContent=names[state.stage]||'Analysis only';$('#stop').classList.toggle('stopped',!!state.stopped);$('#stop').textContent=state.stopped?'■ Automation stopped':'■ Stop automated trading';}
async function refreshState(){state=await api('state');updateStage();}
async function getAnalysis(ticker=selected){if(cache.has(ticker))return cache.get(ticker);const a=await api('analysis?symbol='+encodeURIComponent(ticker));cache.set(ticker,a);return a;}
function source(a){return `${a.history_truncated?`<div class="notice warning section-gap">Provider history contained invalid OHLC. Showing the validated sequence from ${esc(a.bars[0].date)} only. ${esc(a.quality_warnings.join(' '))}</div>`:''}<div class="source">${esc(a.price_type)} · As of ${esc(a.as_of)}<br>${a.source_url?`<a target="_blank" rel="noopener noreferrer" href="${esc(a.source_url)}">${esc(a.source)} ↗</a>`:esc(a.source)}</div>`;}
function nameFor(ticker){return ({'SHOP.TO':'Shopify','005930.KS':'Samsung Electronics','000660.KS':'SK Hynix',AAPL:'Apple',MSFT:'Microsoft',NVDA:'NVIDIA','RY.TO':'Royal Bank of Canada','ENB.TO':'Enbridge','XIU.TO':'iShares S&P/TSX 60 ETF',SPY:'SPDR S&P 500 ETF'})[ticker]||ticker;}
function indicatorCards(a){let i=a.indicators,v=k=>i[k].at(-1),r=v('rsi');return `<div class="grid three section-gap"><button class="card learn-card" data-learn="rsi"><div class="metric-top"><span class="metric-label">Buying & selling pressure</span><span class="mini-icon">≈</span></div><strong class="metric-value">${fmt(r,1)} <small>RSI</small></strong><span class="metric-detail">${r==null?'More history needed':r>=70?'Potentially overbought':r<=30?'Potentially oversold':'Within the neutral range'}</span><p>Strength of recent price moves.</p><span class="learn-link">Learn why ↗</span></button><button class="card learn-card" data-learn="macd"><div class="metric-top"><span class="metric-label">Momentum</span><span class="mini-icon">↗</span></div><strong class="metric-value">${v('histogram')==null?'—':v('histogram')>0?'Above signal':'Below signal'}</strong><span class="metric-detail">MACD histogram ${fmt(v('histogram'))}</span><p>A faster trend compared with a slower one.</p><span class="learn-link">Learn why ↗</span></button><button class="card learn-card" data-learn="bollinger"><div class="metric-top"><span class="metric-label">Volatility</span><span class="mini-icon">⌁</span></div><strong class="metric-value">${v('bb_width')==null?'—':fmt(v('bb_width')*100,1)+'%'}</strong><span class="metric-detail">Bollinger band width</span><p>How much room recent prices have covered.</p><span class="learn-link">Learn why ↗</span></button></div>`;}
function evidenceCard(a){const e=a.evidence,arrow=e.bias==='Bullish'?'↑':e.bias==='Bearish'?'↓':'→';return `<div class="card"><div class="card-head"><h2>What the signals say</h2><span class="pill">EVIDENCE</span></div><span class="metric-label">Technical bias</span><div class="evidence-header"><span class="bias ${e.bias==='Bullish'?'up':e.bias==='Bearish'?'down':'neutral'}">${arrow} ${esc(e.bias)}</span><span class="badge">${esc(e.confidence)} confidence</span></div><h3>Supporting evidence</h3><ul class="evidence-list">${e.positive.map(x=>`<li><span>✓</span>${esc(x)}</li>`).join('')||'<li>Insufficient supporting evidence.</li>'}</ul><div class="divider"></div><h3>Keep in mind</h3><ul class="evidence-list caution">${e.caution.map(x=>`<li><span>△</span>${esc(x)}</li>`).join('')||'<li>No selected caution condition triggered. Risk still exists.</li>'}</ul><small>${esc(e.limitations)}</small></div>`;}
function stockChartCard(a){const last=a.bars.at(-1),quote=a.quote;return `<section class="card"><div class="card-head"><div class="selected-name"><div class="ticker-icon">${esc(selected.slice(0,2))}</div><div><h2>${esc(nameFor(selected))}</h2><small>${esc(selected)} · ${esc(a.market)} · ${esc(a.currency)}</small></div></div><button id="watch" class="text-button">${state.watchlist.includes(selected)?'★ Saved':'☆ Watch'}</button></div><div class="price-line"><strong>${currency(quote?.price??last.close,a.currency)}</strong><span class="${(quote?.regularMarketChangePercent??a.daily_change)>=0?'up':'down'}">${pct(quote?.regularMarketChangePercent??a.daily_change)} ${quote?'session':'last completed day'}</span></div><small>${quote?'Quote as of '+esc(quote.as_of)+(quote.stale?' · Stale':''):'Latest completed adjusted daily close'}</small><div class="chart-tools"><div class="ranges">${['1D','5D','1M','3M','6M','1Y','5Y'].map(x=>`<button data-range="${x}" class="${chartRange===x?'active':''}">${x}</button>`).join('')}</div><label class="check"><input id="bands" type="checkbox"> Bands</label><label class="check"><input id="show-ma" type="checkbox" checked> MA<select id="ma-period" aria-label="Moving average period">${[5,10,20,50,60,120,200].map(n=>`<option ${n===20?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="chart-wrap"><canvas class="chart" id="price-chart" aria-label="Interactive daily candlestick chart" role="img"></canvas></div><div id="chart-tip" class="chart-tip">Hover for date and OHLC · Daily candles · ${esc(chartRange)}</div><div class="legend"><span><i></i>Price</span><span><i class="gold"></i>MA20</span></div>${source(a)}<div class="advanced-only"><div class="stat-grid"><div class="stat"><small>Volume</small><strong>${fmt(last.volume,0)}</strong></div><div class="stat"><small>Market cap</small><strong>${quote?.marketCap?currency(quote.marketCap,a.currency):'Unavailable'}</strong></div><div class="stat"><small>RSI percentile</small><strong>${fmt(a.evidence.rsi_percentile,0)}</strong></div></div></div></section>`;}
function sizeCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);return {c,w:rect.width,h:rect.height};}
function drawCandles(a){const canvas=$('#price-chart');if(!canvas)return;const {c,w,h}=sizeCanvas(canvas),pad=45,top=15,bottom=h-28;let count=({'1D':1,'5D':5,'1M':22,'3M':66,'6M':132,'1Y':252,'5Y':1260})[chartRange];count=Math.min(count,a.bars.length);let offset=a.bars.length-count,bars=a.bars.slice(offset);const lo=Math.min(...bars.map(b=>b.low))*.995,hi=Math.max(...bars.map(b=>b.high))*1.005,y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top),step=(w-pad-8)/count,x=i=>8+(i+.5)*step;
 c.font='11px -apple-system,sans-serif';c.lineWidth=1;
 for(let j=0;j<=4;j++){const value=lo+(hi-lo)*j/4,yy=y(value);c.strokeStyle='#e9edf3';c.beginPath();c.moveTo(5,yy);c.lineTo(w-pad,yy);c.stroke();c.fillStyle='#8a97a9';c.fillText(fmt(value,value>1000?0:1),w-pad+7,yy+3);}
 bars.forEach((b,i)=>{c.strokeStyle=b.close>=b.open?'#397c8e':'#a97a82';c.fillStyle=b.close>=b.open?'#528d9c':'#b28a91';c.beginPath();c.moveTo(x(i),y(b.high));c.lineTo(x(i),y(b.low));c.stroke();c.fillRect(x(i)-Math.max(1,step*.3),y(Math.max(b.open,b.close)),Math.max(1,step*.6),Math.max(1,Math.abs(y(b.open)-y(b.close))));});
 const line=(key,color)=>{c.strokeStyle=color;c.lineWidth=1.4;c.beginPath();let started=false;a.indicators[key].slice(offset).forEach((v,i)=>{if(v==null)return;if(!started){c.moveTo(x(i),y(v));started=true;}else c.lineTo(x(i),y(v));});c.stroke();};if($('#show-ma')?.checked)line('ma'+($('#ma-period')?.value||'20'),'#c29a52');if($('#bands')?.checked){line('bb_upper','#97a6d1');line('bb_lower','#97a6d1');}
 for(const d of a.divergences.filter(d=>d.from>=offset)){c.setLineDash([3,3]);c.strokeStyle=d.kind.toLowerCase().includes('bullish')?'#147963':'#965366';c.beginPath();c.moveTo(x(d.from-offset),y(d.price_from));c.lineTo(x(d.to-offset),y(d.price_to));c.stroke();c.setLineDash([]);for(const index of [d.from,d.to]){c.beginPath();c.arc(x(index-offset),y(index===d.from?d.price_from:d.price_to),3,0,Math.PI*2);c.fillStyle=c.strokeStyle;c.fill();}}
 c.fillStyle='#8a97a9';c.fillText(bars[0].date,8,h-6);c.fillText(bars.at(-1).date,Math.max(8,w-pad-75),h-6);
 canvas.onpointermove=e=>{const i=Math.max(0,Math.min(count-1,Math.floor((e.offsetX-8)/step))),b=bars[i];$('#chart-tip').textContent=`${b.date} · Open ${fmt(b.open)} · High ${fmt(b.high)} · Low ${fmt(b.low)} · Close ${fmt(b.close)} · Volume ${fmt(b.volume,0)}`;};
}
function drawLines(id,points,log=false){const canvas=$('#'+id);if(!canvas||!points?.length)return;const {c,w,h}=sizeCanvas(canvas),pad=45;const convert=v=>log?Math.log(Math.max(.0001,v)):v;const values=points.flatMap(p=>[p.strategy,p.benchmark].filter(v=>v!=null)).map(convert),lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1,x=i=>10+i*(w-pad-10)/Math.max(1,points.length-1),y=v=>h-25-(convert(v)-lo)/span*(h-45);c.font='11px sans-serif';for(let i=0;i<=4;i++){const yy=20+i*(h-45)/4;c.strokeStyle='#e9edf3';c.beginPath();c.moveTo(10,yy);c.lineTo(w-pad,yy);c.stroke();const value=hi-i*span/4;c.fillStyle='#8a97a9';c.fillText(fmt(log?Math.exp(value):value,1),w-pad+5,yy+4);}
 for(const [key,color] of [['benchmark','#b3bdce'],['strategy','#446bdb']]){c.strokeStyle=color;c.lineWidth=2;c.beginPath();let begun=false;points.forEach((p,i)=>{if(p[key]==null)return;if(!begun){c.moveTo(x(i),y(p[key]));begun=true;}else c.lineTo(x(i),y(p[key]));});c.stroke();}c.fillStyle='#8a97a9';c.fillText(points[0].date,10,h-3);c.fillText(points.at(-1).date,w-pad-70,h-3);}
function bindChart(){bind('watch',async()=>{await act('watch',{symbol:selected});await refreshState();$('#watch').textContent=state.watchlist.includes(selected)?'★ Saved':'☆ Watch';});document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{chartRange=b.dataset.range;document.querySelectorAll('[data-range]').forEach(n=>n.classList.toggle('active',n===b));drawCandles(analysis);});for(const id of ['bands','show-ma','ma-period'])if($('#'+id))$('#'+id).onchange=()=>drawCandles(analysis);drawCandles(analysis);drawIndicators(analysis);}
function bindLearn(){document.querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>lesson(b.dataset.learn));}
function lesson(key){const l=state.learn[key];modal(`<span class="eyebrow">LEARN AS YOU GO</span><h2>${esc(l.title)}</h2><p>${esc(l.simple)}</p><h3>What does it measure?</h3><p>${esc(l.calculation)}</p><h3>How should I interpret it?</h3><p>${esc(l.interpretation)}</p><div class="notice warning">${esc(l.uncertainty)}</div>${analysis?`<h3>In your selected stock</h3><p>${esc(selected)} · ${esc(analysis.as_of)}<br>RSI ${fmt(analysis.indicators.rsi.at(-1),1)} · MACD ${fmt(analysis.indicators.macd.at(-1))}</p><small>These values are calculated from the chart's completed daily bars.</small>`:'<p>Select a stock to see a calculated example.</p>'}`);}
async function overview(version){$('#content').innerHTML=loading();let a;try{a=await getAnalysis();}catch(e){if(version!==viewVersion)return;$('#content').innerHTML=errorBox(e)+`<div class="grid equal"><div class="card"><h2>Start with a company</h2><p>Search Samsung Electronics, Shopify or Apple above. Stock101 shows unavailable data honestly.</p>${button('retry','Retry data',true)}</div><div class="card airi-card"><h2>✧ Learn one thing today</h2><p>Discover what momentum can — and cannot — tell you.</p><button class="text-button" data-learn="macd">Explore momentum ↗</button></div></div>`;bind('retry',()=>{cache.delete(selected);return navigate(page);});bindLearn();return;}if(version!==viewVersion)return;analysis=a;
 const last=a.bars.at(-1),tr=a.evidence.trends;
 $('#content').innerHTML=`${a.market==='KR'?`<div class="notice">${esc(state.brokers[0].message)}</div>`:''}<div class="grid three"><div class="card"><div class="metric-top"><span class="metric-label">${esc(dataMarketName())} · Selected stock</span><span class="mini-icon">◉</span></div><strong class="metric-value ${a.daily_change>=0?'up':'down'}">${pct(a.daily_change)}</strong><span class="metric-detail">${esc(selected)} · Last completed session</span></div><div class="card"><div class="metric-top"><span class="metric-label">Your watchlist</span><span class="mini-icon">☆</span></div><strong class="metric-value">${state.watchlist.length} <small>companies & funds</small></strong><button class="text-button" data-page="Watchlist">See your watchlist ↗</button></div><div class="card"><div class="metric-top"><span class="metric-label">Strategy performance</span><span class="mini-icon">⌁</span></div><strong class="metric-value">${state.backtests.length?pct(state.backtests[0].total_return):'Ready to explore'}</strong><span class="metric-detail">${state.backtests.length?'Latest saved backtest · '+esc(state.backtests[0].symbol):'Test an idea against historical data'}</span></div></div><div class="grid two section-gap">${stockChartCard(a)}${evidenceCard(a)}</div>${indicatorCards(a)}<div class="grid equal section-gap advanced-only"><div class="card"><h2>RSI · 14 bars</h2><canvas id="rsi-chart" class="chart chart-small" role="img" aria-label="Historical RSI"></canvas></div><div class="card"><h2>MACD · 12, 26, 9</h2><canvas id="macd-chart" class="chart chart-small" role="img" aria-label="MACD, signal and histogram"></canvas></div></div><div class="grid three section-gap"><div class="card"><h2>Across timeframes</h2>${Object.entries(tr).map(([k,v])=>`<div class="trend-row"><span>${k} term</span><strong class="${v==='Bullish'?'up':'neutral'}">${v==='Bullish'?'↑':'↓'} ${esc(v)}</strong></div>`).join('')}<p class="small section-gap">Different time horizons can disagree. These compare price with 20-, 60- and 200-day averages.</p></div><div class="card airi-card"><h2><span class="airi-star">✧</span>AIRI Market Brief</h2><p>${esc(nameFor(selected))}'s technical readings show a <strong>${esc(a.evidence.bias.toLowerCase())}</strong> bias. Explore the supporting evidence and cautions before drawing a conclusion.</p><button class="text-button" id="brief-ask">Help me understand ↗</button><div class="source">Template summary from calculated indicators · ${esc(a.as_of)}</div></div><div class="card"><h2>Risk monitor</h2><span class="metric-value">Live trading off</span><p class="small">Start with backtesting, then virtual money. Every stage needs your explicit choice.</p><span class="badge">${state.stopped?'Automation stopped':'No automation running'}</span></div></div><div class="grid equal section-gap"><div class="card"><h2>Support & resistance zones</h2>${a.zones.map(z=>`<div class="watch-row"><div><strong class="watch-title">${z.kind} · ${currency(z.low,a.currency)}–${currency(z.high,a.currency)}</strong><small>${z.touches} historical bar touches · ${esc(z.strength)} · ${esc(z.basis.join(', '))}</small></div><span class="small">${pct(z.distance_pct)}</span></div>`).join('')}<div class="source">Zones are estimates. Daily volume clusters are a close-price proxy, not traded volume-at-price.</div></div><div class="card"><h2>Today's signals & divergences</h2><small>Latest completed daily bar, not a real-time alert</small><ul class="evidence-list">${a.evidence.events.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>No crossover on the latest completed bar.</li>'}</ul>${a.divergences.slice(-4).map(d=>`<div class="watch-row"><div><strong class="watch-title">${esc(d.kind)} · ${esc(d.indicator.toUpperCase())}</strong><small>${a.bars[d.from].date} → ${a.bars[d.to].date} · Confirmed ${a.bars[d.confirmed_at].date}</small></div></div>`).join('')||'<p class="small">No confirmed divergence in this dataset.</p>'}<button class="text-button" data-learn="divergence">How to read a divergence ↗</button></div></div>`;
 bindChart();bindLearn();bind('brief-ask',()=>showAnalyst());bindPages();}
function dataMarketName(){return ({KR:'Korea',CA:'Canada',US:'United States'})[market];}
async function marketsPage(version,watch=false){const items=watch?state.watchlist.filter(s=>marketOf(s)===market).map(symbol=>({symbol,name:nameFor(symbol)})):(await api('search?market='+market)).items;if(version!==viewVersion)return;$('#content').innerHTML=`<div class="card"><div class="card-head"><h2>${watch?'Your watchlist':dataMarketName()+' · Starter universe'}</h2><span class="badge">${items.length} instruments</span></div><p class="small">${watch?'Select a company to explore its chart and signals.':'A curated starting point. Search above for other listed stocks and ETFs.'}</p><div id="stock-list">${items.map(x=>`<div class="watch-row"><button data-symbol="${esc(x.symbol)}" class="search-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.symbol)}</small></div><span>Explore ↗</span></button>${watch?`<button data-remove="${esc(x.symbol)}" aria-label="Remove ${esc(x.symbol)}">×</button>`:''}</div>`).join('')||'<div class="empty">Nothing saved in this market yet. Search for a company and choose Watch.</div>'}</div></div>`;bindSymbols();document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{try{await act('watch',{symbol:b.dataset.remove});await refreshState();navigate(page);}catch(e){toast(e.message);}});}
function marketOf(s){return /\.(KS|KQ)$/.test(s)?'KR':/\.(TO|V)$/.test(s)?'CA':'US';}
function selectStock(ticker){selected=ticker;market=marketOf(ticker);localStorage.setItem('stock101.symbol',selected);localStorage.setItem('stock101.market',market);$('#search-results').hidden=true;setMarkets();navigate('Overview');}
function bindSymbols(){document.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>selectStock(b.dataset.symbol));}
function bindPages(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));}
function setMarkets(){document.querySelectorAll('[data-market]').forEach(b=>b.classList.toggle('active',b.dataset.market===market));}
const fields=['price','rsi','macd','signal','histogram','volume','volume_ma20','ma5','ma10','ma20','ma50','ma60','ma120','ma200','bb_upper','bb_lower'];
function opts(values,current){return values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v.replaceAll('_',' '))}</option>`).join('');}
function ruleEditor(node,onChange,depth=0){const box=document.createElement('div');if(node.all||node.any){box.className='rule-group';const key=node.all?'all':'any';box.innerHTML=`<div class="rule-group-header"><select aria-label="Combine conditions"><option value="all" ${key==='all'?'selected':''}>ALL · AND</option><option value="any" ${key==='any'?'selected':''}>ANY · OR</option></select><small>of these conditions</small></div>`;box.querySelector('select').onchange=e=>{const newKey=e.target.value;node[newKey]=node[key];delete node[key];onChange();};node[key].forEach((child,i)=>{const row=document.createElement('div');row.append(ruleEditor(child,onChange,depth+1));const remove=document.createElement('button');remove.textContent='Remove condition';remove.className='text-button';remove.onclick=()=>{if(node[key].length<2)return toast('Keep at least one condition.');node[key].splice(i,1);onChange();};row.append(remove);box.append(row);});const add=document.createElement('button');add.className='text-button';add.textContent='+ Add condition';add.onclick=()=>{if(node[key].length>=12)return toast('Maximum 12 conditions per group.');node[key].push({field:'rsi',op:'below',value:30});onChange();};box.append(add);if(depth<4){const group=document.createElement('button');group.className='text-button';group.textContent='　+ Nested group';group.onclick=()=>{if(node[key].length>=12)return;node[key].push({all:[{field:'price',op:'above',value:'ma200'}]});onChange();};box.append(group);}}else{box.className='rule-row';box.innerHTML=`<select aria-label="Indicator">${opts(fields,node.field)}</select><select aria-label="Comparison">${opts(['below','above','crosses_above','crosses_below'],node.op)}</select><select aria-label="Value type"><option value="number" ${typeof node.value==='number'?'selected':''}>Number</option><option value="indicator" ${typeof node.value==='string'?'selected':''}>Indicator</option></select>${typeof node.value==='number'?`<input type="number" step="any" aria-label="Threshold" value="${esc(node.value)}">`:`<select aria-label="Reference indicator">${opts(fields,node.value)}</select>`}`;const controls=box.querySelectorAll('select,input');controls[0].onchange=e=>node.field=e.target.value;controls[1].onchange=e=>node.op=e.target.value;controls[2].onchange=e=>{node.value=e.target.value==='number'?30:'ma200';onChange();};controls[3].onchange=e=>node.value=typeof node.value==='number'?Number(e.target.value):e.target.value;}return box;}
function strategyPage(){strategy??=structuredClone(state.default_strategy);$('#content').innerHTML=`<div class="notice">Rules are drafts until you review and save them. Saving never enables trading.</div><div class="grid equal"><section class="card"><div class="card-head"><h2>Build your rules</h2><span class="badge">Draft</span></div><label>Strategy name<input id="strategy-name" value="${esc(strategy.name)}" maxlength="100"></label><h3 class="section-gap">When to enter · BUY</h3><div id="entry-editor"></div><h3 class="section-gap">When to exit · SELL</h3><div id="exit-editor"></div><div class="actions">${button('save-strategy','Review & save',true)}${button('test-strategy','Take to backtest')}</div></section><div><section class="card"><h2>Describe your idea</h2><p class="small">A local parser supports the example below in English or Korean. Unrecognized descriptions stay unconverted.</p><textarea id="natural" rows="6" class="full" aria-label="Strategy description">RSI below 30 and MACD crosses above signal and price above 200-day MA, buy. Sell when RSI above 70</textarea><div class="actions">${button('parse-strategy','Preview generated rules')}</div><div id="parse-result"></div></section><section class="card section-gap"><h2>Saved strategies</h2>${state.strategies.map(x=>`<div class="watch-row"><strong class="watch-title">${esc(x.data.name)}</strong><button data-load="${esc(x.id)}" class="text-button">Load ↗</button></div>`).join('')||'<p class="small">Your first idea starts here.</p>'}</section></div></div>`;
 const render=()=>{for(const key of ['entry','exit']){const root=$('#'+key+'-editor');root.replaceChildren(ruleEditor(strategy[key],render));}};render();$('#strategy-name').onchange=e=>strategy.name=e.target.value;
 bind('save-strategy',async()=>{strategy.name=$('#strategy-name').value;modal(`<h2>Review your strategy</h2><p>${esc(strategy.name)}</p><pre>${esc(JSON.stringify(strategy,null,2))}</pre><p class="small">Save this draft for analysis and backtesting. Trading stays off.</p>${button('confirm-save','Save reviewed draft',true)}`);bind('confirm-save',async()=>{await act('save_strategy',{strategy});await refreshState();$('#modal').close();toast('Strategy saved. Trading is unchanged.');navigate('Strategies');});});bind('test-strategy',()=>navigate('Backtest'));bind('parse-strategy',async()=>{const d=await act('parse',{text:$('#natural').value});$('#parse-result').innerHTML=`<h3 class="section-gap">Preview — not activated</h3><pre>${esc(JSON.stringify(d.strategy,null,2))}</pre>${button('accept-rules','Use these draft rules')}`;bind('accept-rules',()=>{strategy=d.strategy;strategyPage();});});document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{strategy=structuredClone(state.strategies.find(x=>x.id===b.dataset.load).data);strategyPage();});}
function backtestPage(){strategy??=structuredClone(state.default_strategy);const today=new Date().toISOString().slice(0,10);$('#content').innerHTML=`<div class="card"><div class="card-head"><div><h2>Test your strategy</h2><small>Whole shares · Long only · Signals at close, execution next open</small></div><button data-page="Strategies" class="text-button">Edit rules ↗</button></div><form id="backtest-form"><div class="form-grid"><label>Ticker<input id="bt-symbol" value="${esc(selected)}" required></label><label>Strategy<select id="bt-strategy"><option value="draft">Current draft · ${esc(strategy.name)}</option>${state.strategies.map(s=>`<option value="${esc(s.id)}">${esc(s.data.name)}</option>`).join('')}</select></label><label>Initial capital (${state.markets[market].currency})<input id="capital" type="number" value="${market==='KR'?100000000:100000}" min="100" required></label><label>From<input id="bt-start" type="date" value="2021-01-01" required></label><label>Through<input id="bt-end" type="date" value="${today}" required></label><label>Position allocation (%)<input id="allocation" type="number" value="2" min="0.1" max="100" step="0.1" required></label><label>Commission per fill<input id="commission" type="number" value="1" min="0" max="10000" step="0.01" required></label><label>Slippage (basis points)<input id="slippage" type="number" value="5" min="0" max="1000" required></label><div class="actions"><button id="run-backtest" class="button primary">Run backtest ↗</button></div></div></form><details><summary class="small">Reviewed strategy rules</summary><pre id="bt-rules">${esc(JSON.stringify(strategy,null,2))}</pre></details></div><div id="backtest-result" class="section-gap"></div><div class="card section-gap"><h2>Test on unseen periods</h2><p class="small">Use one fixed strategy across chronological development, validation and out-of-sample windows. Do not tune the strategy after seeing the final window.</p><div class="form-grid"><label>Development ends<input id="train-end" type="date" value="2022-12-31"></label><label>Validation ends<input id="valid-end" type="date" value="2023-12-31"></label><div class="actions">${button('walk-forward','Evaluate three periods')}</div></div><div id="walk-result"></div></div><div class="card section-gap"><h2>Previous runs</h2>${state.backtests.map(b=>`<div class="watch-row"><div><strong>${esc(b.symbol)}</strong><small>${esc(b.created.slice(0,10))}</small></div><button data-backtest="${esc(b.id)}" class="text-button">${pct(b.total_return)} · Open ↗</button></div>`).join('')||'<p class="small">No completed backtests yet.</p>'}</div>`;
 const collect=()=>({symbol:$('#bt-symbol').value,strategy:$('#bt-strategy').value==='draft'?strategy:state.strategies.find(x=>x.id===$('#bt-strategy').value).data,capital:Number($('#capital').value),commission:Number($('#commission').value),slippage_bps:Number($('#slippage').value),allocation:Number($('#allocation').value)/100,start:$('#bt-start').value,end:$('#bt-end').value});
 $('#bt-strategy').onchange=()=>$('#bt-rules').textContent=JSON.stringify(collect().strategy,null,2);
 $('#backtest-form').onsubmit=async e=>{e.preventDefault();$('#run-backtest').disabled=true;$('#backtest-result').innerHTML=loading('Running locally. Loading historical benchmark data…');try{latestBacktest=await act('backtest',collect());await refreshState();renderBacktest(latestBacktest);}catch(e){$('#backtest-result').innerHTML=errorBox(e);}finally{if($('#run-backtest'))$('#run-backtest').disabled=false;}};
 bind('walk-forward',async()=>{const d=await act('walk_forward',{...collect(),train_end:$('#train-end').value,validation_end:$('#valid-end').value});$('#walk-result').innerHTML=`<div class="grid three">${d.periods.map(p=>`<div class="card"><h3>${esc(p.period)}</h3><strong class="metric-value">${pct(p.total_return)}</strong><small>Drawdown ${fmt(p.max_drawdown)}%<br>${p.closed_trades} closed trades<br>${p.equity[0].date} – ${p.equity.at(-1).date}</small></div>`).join('')}</div><p class="small section-gap">${esc(d.method)}</p>`;});
 document.querySelectorAll('[data-backtest]').forEach(b=>b.onclick=async()=>{try{latestBacktest=await api('backtest?id='+encodeURIComponent(b.dataset.backtest));renderBacktest(latestBacktest);}catch(e){toast(e.message);}});bindPages();if(latestBacktest)renderBacktest(latestBacktest);}
function renderBacktest(d){const r=d.result,metrics=[['Initial capital',currency(r.initial_capital,d.currency)],['Final value',currency(r.final_value,d.currency)],['Total return',pct(r.total_return)],['Annualized return',pct(r.annualized_return)],['Maximum drawdown',fmt(r.max_drawdown)+'%'],['Annual volatility',fmt(r.volatility)+'%'],['Sharpe · risk-free 0',fmt(r.sharpe)],['Win rate',r.win_rate==null?'No closed trades':fmt(r.win_rate)+'%'],['Fills / closed trades',r.number_of_trades+' / '+r.closed_trades],['Average gain',currency(r.average_gain,d.currency)],['Average loss',currency(r.average_loss,d.currency)],['Profit factor',r.profit_factor==null?'Undefined':fmt(r.profit_factor)]];$('#backtest-result').innerHTML=`<div class="card"><div class="card-head"><h2>${esc(d.symbol)} · Results</h2><span class="badge">Historical simulation</span></div><div class="stat-grid">${metrics.map(([k,v])=>`<div class="stat"><span class="metric-label">${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="divider"></div><div class="card-head"><h3>Growth of 100</h3><label class="check"><input id="log-scale" type="checkbox"> Log scale</label></div><canvas id="equity-chart" class="chart" role="img" aria-label="Strategy and benchmark normalized equity"></canvas><div class="legend"><span><i></i>Strategy</span><span>— ${esc(d.benchmark_symbol)} benchmark</span></div>${d.benchmark_error?`<div class="notice warning section-gap">Benchmark unavailable: ${esc(d.benchmark_error)}</div>`:''}<details class="section-gap"><summary class="small">Assumptions & limitations</summary><ul class="outcomes">${r.assumptions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>Open quantity ${r.open_quantity}. Unrealized P/L ${currency(r.unrealized_pnl,d.currency)}. Source: ${esc(d.source)}.</small></details></div><div class="card section-gap"><div class="card-head"><h2>Every trade has a reason</h2><small>Click a row to inspect the signal</small></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Action</th><th>Price</th><th>Quantity</th><th>Fees</th><th>Realized P/L</th></tr></thead><tbody>${r.trades.map((t,i)=>`<tr class="trade" tabindex="0" data-trade="${i}"><td>${t.date}</td><td>${t.action}</td><td>${currency(t.price,d.currency)}</td><td>${t.quantity}</td><td>${currency(t.fees,d.currency)}</td><td>${currency(t.pnl,d.currency)}</td></tr>`).join('')}</tbody></table>${!r.trades.length?'<div class="empty">No rules triggered an executable trade in this window. No performance was invented.</div>':''}</div></div>`;drawLines('equity-chart',r.equity);$('#log-scale').onchange=e=>drawLines('equity-chart',r.equity,e.target.checked);document.querySelectorAll('[data-trade]').forEach(row=>{const open=()=>{const t=r.trades[Number(row.dataset.trade)];modal(`<h2>Why did this trade happen?</h2><p>${t.action} ${t.quantity} ${esc(d.symbol)} · ${t.date}</p><div class="notice">Signal observed at the close on ${t.signal_date}. Filled at the next available open, with slippage.</div><pre>${esc(t.reason)}</pre><p>Fill: ${currency(t.price,d.currency)}<br>Fees: ${currency(t.fees,d.currency)}<br>Realized P/L: ${currency(t.pnl,d.currency)}</p>`);};row.onclick=open;row.onkeydown=e=>{if(e.key==='Enter')open();};});}
async function paperPage(version,portfolio=false){const account=await api('paper?market='+market);if(version!==viewVersion)return;const a=account.account;$('#content').innerHTML=`<div class="notice">Paper mode uses a reviewed historical reference price with fees and adverse slippage. It does not model a live order book, queues or partial fills.</div><div class="grid three"><div class="card"><span class="metric-label">Available virtual cash</span><strong class="metric-value">${currency(a.cash,a.currency)}</strong><span class="metric-detail">${a.currency} account · No FX conversion</span></div><div class="card"><span class="metric-label">Open positions</span><strong class="metric-value">${account.positions.length}</strong><span class="metric-detail">Whole shares · Long only</span></div><div class="card"><span class="metric-label">Realized P/L · visible ledger</span><strong class="metric-value">${currency(account.orders.reduce((s,o)=>s+Number(o.pnl||0),0),a.currency)}</strong><span class="metric-detail">Last ${account.orders.length} orders · Net of fees</span></div></div>${!portfolio?`<div class="card section-gap"><h2>Practice an order</h2><form id="paper-form"><div class="form-grid"><label>Ticker<input id="paper-symbol" value="${esc(selected)}" required></label><label>Action<select id="paper-side"><option>BUY</option><option>SELL</option></select></label><label>Whole shares<input id="paper-qty" type="number" value="1" min="1" step="1" required></label><label>Fee per fill (${a.currency})<input id="paper-fee" type="number" value="1" min="0" step="0.01" required></label><label>Slippage (basis points)<input id="paper-slip" type="number" value="5" min="0" max="1000" required></label><div class="actions"><button class="button primary" id="review-paper">Review paper order</button></div></div></form></div>`:''}<div class="card section-gap"><div class="card-head"><h2>Your holdings</h2>${button('value-portfolio','Calculate current reference value')}</div><div id="portfolio-value"></div><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Shares</th><th>Cost including entry fees</th><th>Average cost</th></tr></thead><tbody>${account.positions.map(p=>`<tr><td><button data-symbol="${esc(p.symbol)}" class="text-button">${esc(p.symbol)}</button></td><td>${p.quantity}</td><td>${currency(p.cost,a.currency)}</td><td>${currency(p.cost/p.quantity,a.currency)}</td></tr>`).join('')}</tbody></table>${!account.positions.length?'<div class="empty">No holdings yet. Review a paper order to begin practicing.</div>':''}</div></div><div class="card section-gap"><h2>Paper order history</h2><div class="table-wrap"><table><thead><tr><th>Created</th><th>Ticker</th><th>Action</th><th>Shares</th><th>Fill price</th><th>Fees</th><th>Status</th></tr></thead><tbody>${account.orders.map(o=>`<tr><td>${esc(o.created.slice(0,16).replace('T',' '))}</td><td>${esc(o.symbol)}</td><td>${o.side}</td><td>${o.quantity}</td><td>${currency(o.price,a.currency)}</td><td>${currency(o.fee,a.currency)}</td><td>PAPER FILLED</td></tr>`).join('')}</tbody></table></div></div>`;
 if(!portfolio)automationPanel();
 bindSymbols();bind('value-portfolio',async()=>{const result=await act('portfolio',{market});$('#portfolio-value').innerHTML=`<div class="notice">Reference equity: ${currency(result.equity,a.currency)} · Unrealized P/L: ${currency(result.unrealized,a.currency)} · Observed drawdown: ${fmt(result.drawdown)}%<br><small>Drawdown uses valuations explicitly taken in Stock101, not a continuous market history. ${result.unavailable.length?'Some prices are unavailable; equity is withheld.':''}</small></div>`;});
 if(!portfolio)$('#paper-form').onsubmit=async e=>{e.preventDefault();$('#review-paper').disabled=true;try{const ticker=$('#paper-symbol').value;if(marketOf(ticker.toUpperCase())!==market)throw Error('Select the matching market before reviewing this ticker.');const r=await act('paper_review',{symbol:ticker,side:$('#paper-side').value,quantity:Number($('#paper-qty').value),fee:Number($('#paper-fee').value),slippage_bps:Number($('#paper-slip').value)});modal(`<span class="eyebrow">ORDER REVIEW · VIRTUAL MONEY ONLY</span><h2>${r.order.side} ${r.order.quantity} ${esc(r.order.symbol)}</h2><p>Broker: Stock101 Paper<br>Reference price: ${currency(r.reference.price,r.reference.currency)}<br>As of: ${esc(r.reference.as_of)}<br>Estimated value with slippage: ${currency(r.estimated_value,r.reference.currency)}<br>Estimated fees: ${currency(r.fees,r.reference.currency)}</p><div class="notice warning">${esc(r.reference.mode)}. This is not a Mirae Asset or IBKR transaction.</div><div class="actions">${button('cancel-order','Cancel')}${button('confirm-paper','Confirm paper order',true)}</div>`);bind('cancel-order',()=>$('#modal').close());bind('confirm-paper',async()=>{await act('paper_confirm',{id:r.order.id});$('#modal').close();toast('Paper order recorded. No real money moved.');navigate(page);});}catch(e){toast(e.message);}finally{if($('#review-paper'))$('#review-paper').disabled=false;}};}
function screenerPage(){$('#content').innerHTML=`<div class="card"><h2>What are you looking for?</h2><p class="small">Search the curated starter universe. A match is a research candidate, not a trade recommendation.</p><label>Describe a supported screen<input id="screen-text" placeholder="캐나다 주식 중 RSI가 35 이하이고 200일 이동평균선 위에 있는 종목 찾아줘."></label><div class="actions">${button('parse-screen','Preview screen filters')}</div><form id="screen-form"><div class="form-grid"><label>RSI at or below<input id="rsi-max" type="number" min="0" max="100" value="100"></label><label>Sector<select id="screen-sector"><option value="">All sectors</option><option>Technology</option><option>Financials</option><option>Energy</option><option>Materials</option><option>Communication</option><option>ETF</option></select></label><label>Minimum price<input id="screen-price" type="number" min="0" value="0"></label><label>Minimum daily volume<input id="screen-volume" type="number" min="0" value="0"></label><label>Minimum market cap<input id="screen-cap" type="number" min="0" value="0"></label></div><div class="checks">${[['above_ma200','Price above MA200'],['macd_positive','MACD above signal'],['volume_spike','Volume ≥ 1.4× average'],['squeeze','Bollinger squeeze'],['near_support','Within 3% of support'],['near_resistance','Within 3% of resistance']].map(([id,text])=>`<label class="check"><input type="checkbox" id="${id}">${text}</label>`).join('')}</div><button id="run-screen" class="button primary">Find matches ↗</button></form></div><div id="screen-results" class="section-gap"></div>`;
 bind('parse-screen',()=>{const t=$('#screen-text').value.trim();const m=t.match(/^캐나다 주식 중 RSI가\s*(\d+(?:\.\d+)?)\s*이하이고\s*200일 이동평균선 위에 있는 종목 찾아줘\.?$/i)||t.match(/^Canadian stocks with RSI (?:below|at or below) (\d+(?:\.\d+)?) and price above (?:the )?200[- ]day moving average\.?$/i);if(!m||Number(m[1])>100)throw Error('Use the illustrated Korean screen or: Canadian stocks with RSI below 35 and price above 200-day moving average');market='CA';setMarkets();$('#rsi-max').value=m[1];$('#above_ma200').checked=true;toast('Preview: Canada, RSI ≤ '+m[1]+', price above MA200. Review before running.');});
 $('#screen-form').onsubmit=async e=>{e.preventDefault();$('#run-screen').disabled=true;$('#screen-results').innerHTML=loading('Checking each stock against your filters…');try{const filters={rsi_max:Number($('#rsi-max').value),price_min:Number($('#screen-price').value),volume_min:Number($('#screen-volume').value),cap_min:Number($('#screen-cap').value),sector:$('#screen-sector').value};for(const k of ['above_ma200','macd_positive','volume_spike','squeeze','near_support','near_resistance'])filters[k]=$('#'+k).checked;const d=await act('screener',{market,filters});$('#screen-results').innerHTML=`<div class="card"><div class="card-head"><h2>${d.items.length} matches</h2><small>${esc(d.universe)}</small></div>${d.items.map(x=>`<button data-symbol="${esc(x.symbol)}" class="search-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.symbol)} · ${esc(x.sector)} · ${esc(x.as_of)}</small></div><div>${fmt(x.price)}<small>RSI ${fmt(x.rsi,1)}</small></div></button>`).join('')||'<div class="empty">No matches. Try broader filters.</div>'}${d.unavailable.length?`<details><summary>${d.unavailable.length} unavailable instruments</summary>${d.unavailable.map(x=>`<p class="small">${esc(x.symbol)}: ${esc(x.error)}</p>`).join('')}</details>`:''}</div>`;bindSymbols();}catch(e){$('#screen-results').innerHTML=errorBox(e);}finally{if($('#run-screen'))$('#run-screen').disabled=false;}};}
async function newsPage(version){$('#content').innerHTML=loading('Fetching dated sources for '+selected+'…');const d=await api('news?symbol='+encodeURIComponent(selected));if(version!==viewVersion)return;const total=d.items.length;$('#content').innerHTML=`<div class="notice">${esc(d.method)}</div><div class="grid three">${Object.entries(d.counts).map(([label,n])=>`<div class="card"><span class="metric-label">${label} headline cues</span><strong class="metric-value">${total?fmt(n/total*100,0)+'%':'—'}</strong><small>${n} of ${total} articles</small></div>`).join('')}</div><div class="card section-gap"><div class="card-head"><h2>${esc(selected)} · Recent sources</h2><small>Last 7 days</small></div>${d.items.map(n=>`<article class="news-item"><div class="news-meta">${esc(n.source)} · ${esc(new Date(n.published_at).toLocaleString())} · ${esc(n.market)} · ${esc(n.ticker)}</div><h3><a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">${esc(n.headline)} ↗</a></h3><span class="badge">${esc(n.sentiment)} headline cue</span></article>`).join('')||'<div class="empty">No recent articles with complete source, timestamp and URL were returned. No news summary has been invented.</div>'}</div>`;}
function learnPage(){$('#content').innerHTML=`<div class="grid three">${Object.entries(state.learn).map(([key,l],i)=>`<button class="card learn-card" data-learn="${key}"><span class="learn-number">LESSON ${String(i+1).padStart(2,'0')}</span><h2>${esc(l.title)}</h2><p>${esc(l.simple)}</p><span class="learn-link">Explore the idea ↗</span></button>`).join('')}</div>`;bindLearn();}
function settingsPage(){const names=['Analysis only','Backtesting','Paper trading','Manual live orders','Automated live trading'];$('#content').innerHTML=`<div class="card"><h2>Progress at your own pace</h2><p class="small">Each stage is explicit. Live stages remain unavailable until an official broker integration is commissioned and tested.</p><div class="stages">${names.map((n,i)=>`<div class="stage ${i<=state.stage?'enabled':''}"><span>LEVEL ${i}</span><strong>${n}</strong><small>${i<=state.stage?'Enabled':i>2?'Not commissioned':'Not enabled'}</small></div>`).join('')}</div>${state.stage<2?button('next-stage','Enable '+names[state.stage+1],true):'<span class="badge">Paper mode ready · Live transport disabled</span>'}</div><div class="card section-gap"><h2>Broker connections</h2>${state.brokers.map(b=>`<div class="watch-row"><div><strong>${esc(b.name)}</strong><small>${esc(b.status)}</small><p class="small">${esc(b.message)}</p></div><button class="text-button" data-broker="${esc(b.name)}">Check access ↗</button></div>`).join('')}<details><summary class="small">Official interfaces & setup</summary><p class="small">IBKR: authenticate in the local Client Portal Gateway. Set STOCK101_IBKR_GATEWAY to https://localhost:5000/v1/api and STOCK101_IBKR_ACCOUNT in the service environment. Trust its certificate through your operating system; certificate verification is never disabled.<br>Questrade: configure the official OAuth-returned STOCK101_QUESTRADE_SERVER, STOCK101_QUESTRADE_TOKEN and STOCK101_QUESTRADE_ACCOUNT in the service environment. Tokens expire; use Questrade's authentication flow to renew them. Stock101 does not store passwords.</p></details></div><div class="card section-gap"><h2>Risk controls</h2><p class="small">Defaults are software limits, not investment recommendations. These guard the future live gateway; paper simulations use only available cash and shares.</p><form id="risk-form"><div class="form-grid">${Object.entries(state.limits).map(([k,v])=>`<label>${esc(k.replaceAll('_',' '))} (%)<input data-limit="${k}" type="number" min="0.01" max="100" step="0.01" value="${v*100}" required></label>`).join('')}</div><button class="button primary">Save controls</button></form></div><div class="card section-gap"><h2>Bring your own price history</h2><p class="small">CSV columns: date, open, high, low, close, volume. Daily bars must be chronological. Imported data replaces the provider history for this ticker until removed.</p><form id="import-form"><div class="form-grid"><label>Ticker<input id="import-symbol" value="${esc(selected)}" required></label><label>Source & adjustment method<input id="import-source" required placeholder="Provider, export date, adjusted OHLC"></label><label>Daily OHLCV CSV<input type="file" accept=".csv,text/csv" id="import-file" required></label></div><label class="check"><input type="checkbox" id="adjusted"> All OHLC values are adjusted consistently for splits and dividends</label><div class="actions"><button class="button primary">Import local CSV</button>${button('remove-import','Use provider history again')}</div></form></div><div class="card section-gap"><h2>Activity log</h2>${button('load-audit','View safety & paper events')}<div id="audit"></div></div>`;
 bind('next-stage',async()=>{await act('stage',{stage:state.stage+1});await refreshState();settingsPage();toast('Stage enabled.');});document.querySelectorAll('[data-broker]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const d=await act('broker_check',{broker:b.dataset.broker});modal(`<h2>${esc(b.dataset.broker)} · Account response</h2><pre>${esc(JSON.stringify(d.data,null,2))}</pre><p>Read access does not enable live trading.</p>`);}catch(e){toast(e.message);}finally{b.disabled=false;}});
 $('#risk-form').onsubmit=async e=>{e.preventDefault();try{const limits={};document.querySelectorAll('[data-limit]').forEach(i=>limits[i.dataset.limit]=Number(i.value)/100);await act('limits',{limits});await refreshState();toast('Risk controls saved.');}catch(e){toast(e.message);}};
 $('#import-form').onsubmit=async e=>{e.preventDefault();try{const file=$('#import-file').files[0];if(file.size>150000)throw Error('Use a CSV smaller than 150 KB.');const ticker=$('#import-symbol').value;const d=await act('import',{symbol:ticker,source:$('#import-source').value,csv:await file.text(),adjusted:$('#adjusted').checked});cache.clear();toast(d.bars+' daily bars imported.');}catch(e){toast(e.message);}};
 bind('remove-import',async()=>{await act('remove_import',{symbol:$('#import-symbol').value});cache.clear();toast('Provider history restored.');});bind('load-audit',async()=>{const d=await api('audit');$('#audit').innerHTML=d.items.map(x=>`<details class="section-gap"><summary>${esc(x.kind)} · ${esc(x.created)}</summary><pre>${esc(x.payload)}</pre></details>`).join('')||'<p class="small section-gap">No safety or paper events yet.</p>';});}
function showAnalyst(){$('#analyst').hidden=false;$('#question').focus();}
$('#ask-toggle').onclick=showAnalyst;$('#ask-close').onclick=()=>$('#analyst').hidden=true;
$('#ask-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#answer').innerHTML='<p class="loading">Reading the selected stock’s calculations…</p>';try{const d=await act('analyst',{symbol:selected,question:$('#question').value,use_local_llm:$('#local-llm').checked});$('#answer').innerHTML=[['FACT',d.fact],['CALCULATION',Object.entries(d.calculation).map(([k,v])=>k.toUpperCase()+': '+fmt(v)).join('\n')],['INTERPRETATION',d.interpretation],['UNCERTAINTY',d.uncertainty]].map(([label,text])=>`<div class="answer-block"><b>${label}</b><p>${esc(text)}</p></div>`).join('')+d.comparison.map(c=>`<div class="notice">Comparison: ${esc(c.symbol)} · ${esc(c.as_of)}<br>RSI ${fmt(c.rsi)} · ${esc(c.bias)}</div>`).join('')+`<small>${esc(d.method)}</small>`;}catch(e){$('#answer').innerHTML=`<p>${esc(e.message)}</p>`;}finally{b.disabled=false;}};
$('#stop').onclick=async()=>{try{const d=await act('stop');await refreshState();toast('Automation stopped. Positions were not liquidated.');modal(`<h2>Automated trading stopped</h2><p>New automated orders are blocked by the persisted safety latch.</p><p>${esc(d.cancellation)}</p><div class="notice">Your positions have not been liquidated. The event is recorded in the local activity log.</div>`);}catch(e){toast(e.message);}};
$('#search-form').onsubmit=async e=>{e.preventDefault();$('#search-results').hidden=false;$('#search-results').textContent='Searching…';try{const d=await api('search?market='+market+'&q='+encodeURIComponent($('#search').value));$('#search-results').innerHTML=d.items.map(x=>`<button class="search-row" data-symbol="${esc(x.symbol)}"><span>${esc(x.name)}</span><small>${esc(x.symbol)} ↗</small></button>`).join('')||'<p class="small">No matches in this market. Try a ticker with the exchange suffix.</p>';bindSymbols();}catch(e){$('#search-results').textContent=e.message;}};
$('#beginner').checked=localStorage.getItem('stock101.beginner')!=='false';document.body.classList.toggle('advanced',!$('#beginner').checked);$('#beginner').onchange=e=>{document.body.classList.toggle('advanced',!e.target.checked);localStorage.setItem('stock101.beginner',e.target.checked);if(analysis)drawIndicators(analysis);};
$('#navigation').innerHTML=pages.map((p,i)=>`<button class="navitem" data-page="${p}"><span class="navicon">${icons[i]}</span><span>${p}</span></button>`).join('');
document.querySelectorAll('[data-market]').forEach(b=>b.onclick=()=>{market=b.dataset.market;localStorage.setItem('stock101.market',market);selected=({KR:'005930.KS',CA:'SHOP.TO',US:'AAPL'})[market];localStorage.setItem('stock101.symbol',selected);analysis=null;setMarkets();navigate(page);});
async function navigate(next){page=next;const version=++viewVersion;$('#crumb').textContent=next;$('#heading').textContent=labels[next][0];$('#subheading').textContent=labels[next][1];document.querySelectorAll('.navitem').forEach(b=>b.classList.toggle('active',b.dataset.page===next));$('#content').innerHTML=loading('Opening your workspace…');try{if(next==='Overview')await overview(version);else if(next==='Markets'||next==='Watchlist')await marketsPage(version,next==='Watchlist');else if(next==='Strategies')strategyPage();else if(next==='Backtest')backtestPage();else if(next==='Paper Trading'||next==='Portfolio')await paperPage(version,next==='Portfolio');else if(next==='News')await newsPage(version);else if(next==='Screener')screenerPage();else if(next==='Learn')learnPage();else if(next==='Settings')settingsPage();else if(next==='Trading Vault')await vaultPage(version);}catch(e){if(version===viewVersion)$('#content').innerHTML=errorBox(e);}bindPages();}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if($('#price-chart')&&analysis)drawCandles(analysis);if($('#equity-chart')&&latestBacktest)drawLines('equity-chart',latestBacktest.result.equity,$('#log-scale')?.checked);},150);});
(async()=>{try{const bootstrap=await fetch('/api/bootstrap');token=(await bootstrap.json()).token;await refreshState();setMarkets();bindPages();navigate('Overview');if(!state.onboarded){modal(`<span class="eyebrow">WELCOME TO STOCK101</span><h1>A good place to begin.</h1><p>You don't need to know the formulas.<br>What would you like to do?</p><div class="modal-options">${[['Learn','Learn stock analysis'],['Markets','Analyze a stock'],['Strategies','Build a strategy'],['Backtest','Backtest a strategy'],['Paper Trading','Paper trade']].map(([p,t])=>`<button data-start="${p}">${t} <span>↗</span></button>`).join('')}</div><p class="small section-gap">No API keys needed to start learning. Live trading is disabled.</p>`);document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{try{await act('onboard');state.onboarded=true;$('#modal').close();navigate(b.dataset.start);}catch(e){toast(e.message);}});}}catch(e){$('#content').innerHTML=errorBox(e);}})();

async function vaultPage(version){const d=await api('vault');if(version!==viewVersion)return;$('#content').innerHTML=`<div class="notice">Imported from Trading_Vault.zip · ${d.documents.length} notes. These documents are reference material, not runtime commands. Crypto and live trading remain disabled.</div><div class="grid equal"><div class="card"><h2>Browse the vault</h2>${d.documents.map((x,i)=>`<button class="search-row" data-vault="${i}"><span>${esc(x.title)}</span><small>Read ↗</small></button>`).join('')}</div><div><div class="card"><h2>How this maps to Stock101</h2><div class="watch-row"><span>Local SQLite & separate services</span><span class="badge">Implemented</span></div><div class="watch-row"><span>LLM outside the order path</span><span class="badge">Implemented</span></div><div class="watch-row"><span>Review, idempotency & activity log</span><span class="badge">Implemented</span></div><div class="watch-row"><span>Broker order lifecycle & reconciliation</span><span class="badge">Not commissioned</span></div><div class="watch-row"><span>Independent watchdog & Telegram kill</span><span class="badge">Pending</span></div><div class="watch-row"><span>Crypto & Canadian tax ACB</span><span class="badge">Reference scope</span></div><p class="small section-gap">The vault proposes a 10% position limit and 2% daily loss limit. Your Stock101 brief specifies 5% and 3%. Stock101 retains its original defaults; neither document is silently treated as a live authorization. The vault's proposed stack does not replace AIRI's existing stack.</p><div class="notice warning">Risk limits are controls, not guarantees. Losses can exceed planned thresholds during gaps, outages or poor liquidity. Paper fills are not evidence of broker execution readiness.</div></div><div id="vault-note" class="card section-gap"><h2>Select a note</h2><p class="small">The complete original text, including its status and open questions, is preserved.</p></div></div></div>`;document.querySelectorAll('[data-vault]').forEach(b=>b.onclick=()=>{const n=d.documents[Number(b.dataset.vault)];$('#vault-note').replaceChildren();const h=document.createElement('h2');h.textContent=n.title;const pre=document.createElement('pre');pre.textContent=n.content;$('#vault-note').append(h,pre);});}

function automationPanel(){const root=document.createElement('section');root.className='card section-gap';root.innerHTML=`<div class="card-head"><h2>Automatic paper orders</h2><span class="badge">Daily replay · Live disabled</span></div><p class="small">Stock101 checks once a minute while AIRI is running. After a new daily bar is completed, it evaluates the previous bar's closing signal and simulates a fill at that new bar's opening price. This is delayed daily replay, not intraday execution. Arming starts with the next completed bar; it never trades old signals immediately.</p><form id="auto-form"><div class="form-grid"><label>Saved strategy<select id="auto-strategy" required><option value="">Choose a reviewed strategy</option>${state.strategies.map(x=>`<option value="${esc(x.id)}">${esc(x.data.name)}</option>`).join('')}</select></label><label>Ticker<input id="auto-symbol" value="${esc(selected)}" required></label><label>Fixed whole shares per entry<input id="auto-qty" type="number" min="1" value="1" required></label><label>Fee per fill<input id="auto-fee" type="number" min="0" step="0.01" value="1"></label><label>Slippage (basis points)<input id="auto-slip" type="number" min="0" max="1000" value="5"></label></div><label class="check"><input id="auto-review" type="checkbox" required>I reviewed the strategy and understand that this creates simulated paper orders only.</label><div class="actions"><button class="button primary">Arm automatic paper orders</button>${button('cycle-paper','Check for a new completed bar')}</div></form><div class="section-gap">${(state.automations||[]).map(x=>`<div class="watch-row"><div><strong>${esc(x.data.symbol)} · ${esc(x.data.name)}</strong><small>${x.data.enabled?'Armed':'Paused'} · ${esc(x.data.last_result?.status||x.data.last_result?.code||'Waiting')} · After ${esc(x.data.armed_after)}</small></div>${x.data.enabled?`<button class="text-button" data-disarm="${esc(x.id)}">Disarm</button>`:''}</div>`).join('')}</div>${state.stopped?`<div class="notice warning section-gap">The stop switch is engaged. Releasing it will not rearm any strategy.</div><label>Reason to release the paper stop<input id="release-reason" minlength="10" maxlength="500"></label><div class="actions">${button('release-stop','Release paper stop')}</div>`:''}`;$('#content').append(root);$('#auto-form').onsubmit=async e=>{e.preventDefault();try{await act('arm_paper',{strategy_id:$('#auto-strategy').value,symbol:$('#auto-symbol').value,quantity:Number($('#auto-qty').value),fee:Number($('#auto-fee').value),slippage_bps:Number($('#auto-slip').value),reviewed:$('#auto-review').checked});await refreshState();navigate('Paper Trading');toast('Automatic paper strategy armed. Waiting for a new completed daily bar.');}catch(e){toast(e.message);}};bind('cycle-paper',async()=>{const d=await act('paper_cycle');await refreshState();navigate('Paper Trading');toast(d.results?.length?'Paper cycle recorded.':'No new completed bar or no armed strategies.');});document.querySelectorAll('[data-disarm]').forEach(b=>b.onclick=async()=>{try{await act('disarm_paper',{id:b.dataset.disarm});await refreshState();navigate('Paper Trading');}catch(e){toast(e.message);}});bind('release-stop',async()=>{await act('release_paper_stop',{reason:$('#release-reason').value});await refreshState();navigate('Paper Trading');});}

function drawIndicators(a){for(const [id,keys] of [['rsi-chart',['rsi']],['macd-chart',['macd','signal']]]){const canvas=$('#'+id);if(!canvas||!canvas.getBoundingClientRect().width)continue;const {c,w,h}=sizeCanvas(canvas),n=Math.min(252,a.bars.length),series=keys.map(k=>a.indicators[k].slice(-n)),values=series.flat().filter(x=>x!=null),lo=id==='rsi-chart'?0:Math.min(0,...values),hi=id==='rsi-chart'?100:Math.max(0,...values),x=i=>10+i*(w-50)/Math.max(1,n-1),y=v=>h-15-(v-lo)/(hi-lo||1)*(h-30);c.font='11px sans-serif';for(const v of id==='rsi-chart'?[30,70]:[0]){c.strokeStyle='#dbe2ec';c.beginPath();c.moveTo(10,y(v));c.lineTo(w-35,y(v));c.stroke();c.fillStyle='#7c8da5';c.fillText(String(v),w-30,y(v)+4);}if(id==='macd-chart'){a.indicators.histogram.slice(-n).forEach((v,i)=>{if(v==null)return;c.fillStyle=v>=0?'#91b6c5':'#d1b3b9';c.fillRect(x(i),Math.min(y(v),y(0)),Math.max(1,(w-50)/n*.7),Math.max(1,Math.abs(y(v)-y(0))));});}series.forEach((vs,j)=>{c.strokeStyle=j?'#c29a52':'#5479d5';c.lineWidth=1.5;c.beginPath();let first=true;vs.forEach((v,i)=>{if(v==null)return;if(first){c.moveTo(x(i),y(v));first=false;}else c.lineTo(x(i),y(v));});c.stroke();});}}
